using System;using System.Linq;using System.Xml;using System.Globalization;using System.Text.RegularExpressions;
namespace BeamScheduleFormatter {
// Manual schedules reuse the slab estimator; the independent DXF formatter stays unchanged.
static class ManualSlabSchedule {
 internal static bool IsManual(string raw){return (raw??"").TrimStart().StartsWith("<ManualSlabSchedule",StringComparison.Ordinal);}
 internal static System.Collections.Generic.List<SlabScheduleRow> ReadSource(string raw){return IsManual(raw)?new System.Collections.Generic.List<SlabScheduleRow>{Read(raw)}:SlabScheduleReader.Read(raw);}
 internal static SlabScheduleRow Create(string mark,string thickness,string[][] groups){mark=(mark??"").Trim();if(!Regex.IsMatch(mark,@"^[A-Za-z][A-Za-z0-9_-]*$"))throw new Exception("Enter a unique slab mark using letters, digits, dash or underscore.");double depth=Positive(thickness,"slab thickness");if(groups==null||groups.Length!=9)throw new Exception("Enter the nine slab reinforcement groups.");var bars=new SlabBar[9];for(int n=0;n<9;n++){var g=groups[n];if(g==null||g.Length!=3)throw new Exception("Invalid manual reinforcement group.");if(string.IsNullOrWhiteSpace(g[0])&&string.IsNullOrWhiteSpace(g[2]))continue;int diameter;if(!int.TryParse(g[0],out diameter)||!new[]{6,8,10,12,16,20,25,28,32,36,40,50}.Contains(diameter))throw new Exception(SlabScheduleReader.Columns[n]+": choose a supported bar diameter.");double value=Positive(g[2],SlabScheduleReader.Columns[n]);var bar=new SlabBar{Diameter=diameter};if(g[1]=="Number of bars"){if(value<2||value>int.MaxValue||value!=Math.Floor(value))throw new Exception("Manual bar count must be a whole number of at least 2 bars per panel/support strip.");bar.ExplicitCount=(int)value;bar.Raw=bar.ExplicitCount+" pcs Ø"+diameter+" per panel / support strip";}else if(g[1]=="Spacing (mm)"){bar.SpacingMm=value;bar.Raw="Ø"+diameter+" @ "+value.ToString("0.###",CultureInfo.InvariantCulture)+" mm C/C";}else throw new Exception("Select spacing or number of bars.");bars[n]=bar;}if(bars.All(b=>b==null))throw new Exception("Enter at least one reinforcement group.");return new SlabScheduleRow{Mark=mark.Trim().ToUpperInvariant(),Thickness=depth,Bars=bars,Manual=true};}
 static double Positive(string text,string name){double value;if(!double.TryParse(text,NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value)||value<=0)throw new Exception("Enter positive "+name+".");return value;}
 internal static string Write(SlabScheduleRow row){var doc=new XmlDocument{XmlResolver=null};var root=doc.CreateElement("ManualSlabSchedule");root.SetAttribute("version","1");root.SetAttribute("mark",row.Mark);root.SetAttribute("thickness",row.Thickness.ToString("R",CultureInfo.InvariantCulture));doc.AppendChild(root);for(int n=0;n<9;n++){var bar=row.Bars[n];if(bar==null)continue;var e=doc.CreateElement("Bar");e.SetAttribute("group",n.ToString());e.SetAttribute("diameter",bar.Diameter.ToString());e.SetAttribute("method",bar.ExplicitCount>0?"Number of bars":"Spacing (mm)");e.SetAttribute("value",bar.ExplicitCount>0?bar.ExplicitCount.ToString():bar.SpacingMm.ToString("R",CultureInfo.InvariantCulture));root.AppendChild(e);}return doc.OuterXml;}
 internal static SlabScheduleRow Read(string xml){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(new System.IO.StringReader(xml),new XmlReaderSettings{XmlResolver=null,DtdProcessing=DtdProcessing.Prohibit}))doc.Load(reader);var root=doc.DocumentElement;if(root.Name!="ManualSlabSchedule"||root.GetAttribute("version")!="1")throw new Exception("Invalid manual slab schedule.");var groups=Enumerable.Range(0,9).Select(n=>new[]{"","Spacing (mm)",""}).ToArray();var used=new System.Collections.Generic.HashSet<int>();foreach(XmlElement e in root.SelectNodes("Bar")){int index;if(!int.TryParse(e.GetAttribute("group"),out index)||index<0||index>=9||!used.Add(index))throw new Exception("Invalid or duplicate manual slab reinforcement group.");groups[index]=new[]{e.GetAttribute("diameter"),e.GetAttribute("method"),e.GetAttribute("value")};}return Create(root.GetAttribute("mark"),root.GetAttribute("thickness"),groups);}
 internal static int Count(SlabBar bar,double width,double cover){if(bar.ExplicitCount<=0)return SlabEstimatorEngine.Count(width,bar.SpacingMm,cover);if(bar.ExplicitCount<2||double.IsNaN(width)||double.IsInfinity(width)||double.IsNaN(cover)||double.IsInfinity(cover)||cover<0||width*1000<=2*cover)throw new Exception("Check manual bar count, panel width and cover.");return bar.ExplicitCount;}
}
}
